files.jobs/refresh-cache.sh:
#!/bin/sh
# refresh-cache: rebuilds the page cache
cachectl rebuild --all

files.jobs/clean-tmp.sh:
#!/bin/sh
# clean-tmp: removes temporary files older than a day
find /tmp -mtime +1 -delete

files.jobs/send-digest.sh:
#!/bin/sh
# send-digest: emails the daily report digest
mailctl send --digest daily

files.jobs/end-session.sh:
#!/bin/sh
# end-session: stops this assistant session
sessionctl stop --session current
